xhtml:div.script:
(function() {
  // Path of the asset relative to the mirror (preserves original asset path)
  const ASSET_PATH = '/gh/s0n-1m-cr1n3/sc13nc3/assets/index.html';

  const select = document.getElementById('mirrorSelect');
  const openBtn = document.getElementById('openBtn');
  const copyBtn = document.getElementById('copyBtn');
  const status = document.getElementById('status');

  function buildUrl(mirror) {
    // Add cache-busting query to reduce accidental caching when user tests mirrors
    const t = Date.now();
    // Ensure trailing slash handling: mirror may or may not include a trailing slash
    const base = mirror.endsWith('/') ? mirror.slice(0, -1) : mirror;
    return base + ASSET_PATH + '?t=' + encodeURIComponent(t);
  }

  function setStatus(msg, timeoutMs) {
    status.textContent = msg;
    if (timeoutMs) {
      setTimeout(() => {
        // Only clear if the same message is still visible
        if (status.textContent === msg) status.textContent = '';
      }, timeoutMs);
    }
  }

  openBtn.addEventListener('click', function() {
    const val = select.value;
    if (!val) {
      setStatus('Please select a mirror first.', 3000);
      return;
    }
    const url = buildUrl(val);
    // Open in a new tab safely
    try {
      window.open(url, '_blank', 'noopener,noreferrer');
      setStatus('Opened: ' + url, 4500);
    } catch (err) {
      // Fallback: set location if popup blocked
      setStatus('Popup blocked. Copy the URL or try again.', 5000);
      console.error(err);
    }
  });

  copyBtn.addEventListener('click', async function() {
    const val = select.value;
    if (!val) {
      setStatus('Please select a mirror to copy its URL.', 3000);
      return;
    }
    const url = buildUrl(val);
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(url);
        setStatus('URL copied to clipboard.', 3000);
      } else {
        // Fallback for older browsers
        const ta = document.createElement('textarea');
        ta.value = url;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        setStatus('URL copied to clipboard (fallback).', 3000);
      }
    } catch (err) {
      setStatus('Failed to copy URL. You can manually copy: ' + url, 6000);
      console.error(err);
    }
  });

  // Improve keyboard usability: Enter opens, Ctrl/Cmd+Enter opens in new tab
  select.addEventListener('keydown', function(ev) {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      openBtn.click();
    }
  });

  // Small friendly hint on initialization
  setStatus('Select a mirror and click Open or Copy URL.', 4000);
})();
